arguments.command:
python3 -c "
from openpyxl import load_workbook
wb = load_workbook('budget.xlsx')
ws = wb['Budget']
print('Dims:', ws.dimensions)
for row in ws.iter_rows(min_row=1, max_row=25, max_col=3):
    for c in row:
        if c.value is not None:
            print(c.coordinate, repr(c.value), '| font color:', c.font.color.rgb if c.font.color else None, '| numfmt:', c.number_format)
"
